from pathlib import Path
import json
P=Path(__file__).resolve().parents[1]
E={
1:r'''惯性系 $S$ 与动系 $S'$ 共用固定原点 $O$。$S'$ 绕共同的竖直轴 $Z$ 以恒角速率 $\Omega>0$ 逆时针转动，$t=0$ 时两系水平轴重合。矢量 $\vect G=G_0\vect e_1$ 固定在动系中，$G_0$ 为常数。求 $(\dd\vect G/\dd t)_S$ 和 $(\dd\vect G/\dd t)_{S'}$，并说明二者为什么不同。''',
2:r'''两系共用固定原点，动系以 $\Omega\vect e_Z$ 匀速转动，$t=0$ 时 $\vect e_1=\vect e_X$、$\vect e_2=\vect e_Y$。矢量 $\vect G=G_0\vect e_X$ 在惯性空间中恒定。求它在动系中的两个水平分量及动系矢量导数，并用运输定理核验惯性系导数。''',
3:r'''动系相对惯性系绕共同的 $Z$ 轴转过角度 $\theta(t)$，正向按右手定则规定。动系分量到惯性系分量的变换矩阵为
\[Q=\begin{pmatrix}\cos\theta&-\sin\theta&0\\\sin\theta&\cos\theta&0\\0&0&1\end{pmatrix}.\]
直接计算 $\dot Q Q^{\mathsf T}$，由其反对称结构确定瞬时角速度。讨论该结论是否要求匀速转动。''',
4:r'''两个正交框架共用固定原点与竖轴 $\vect e_3=\vect E_Z$。框架甲的水平轴固定，框架乙的水平轴以恒角速率 $\Omega$ 绕 $Z$ 轴转动。已知两者都有 $\dot{\vect e}_3=0$，能否据此认定两个框架相同？分别写出它们的角速度，并说明仅给一根轴的方向为何不够。''',
5:r'''一根水平径向直管绕固定竖轴 $OZ$ 以恒角速率 $\Omega>0$ 转动。取沿管向外为 $\vect e_1$，逆时针切向为 $\vect e_2$。质点由装置控制，按 $r(t)=r_0+ut$ 沿管向外匀速滑动，其中 $u>0$、$r_0\ge0$。求惯性系加速度的径向与切向分量，并解释相对加速度为零时绝对加速度为何不为零。''',
6:r'''小车上的原点 $O'$ 沿惯性 $X$ 方向以加速度 $A$ 平动。一根水平直管绕 $O'$ 以恒角速率 $\Omega>0$ 转动，当前管轴与 $X$ 轴夹角为 $\theta$。质点距 $O'$ 为 $r$，以恒定相对速率 $u$ 沿管向外滑动。取沿管为 $\vect e_1$、正切向为 $\vect e_2$，求绝对加速度的两个分量。''',
7:r'''动系角速度为 $\Om$，质点的相对速度为 $\vect v'$，科氏加速度为 $2\Om\times\vect v'$。分别考察：参考系不转动；质点固定在动系；质点相对运动平行于转轴。判断每种情况下科氏项是否为零，并给出科氏项消失的统一条件。相对速率恒定或相对轨迹为直线，是否已足够？''',
8:r'''一根长度为 $R$ 的水平直管，一端 $O$ 位于固定竖直转轴上，管以恒角速率 $\Omega>0$ 逆时针转动。质点受控制，以相对速率 $u>0$ 沿管向外匀速移动。分别求其经过 $r=R/3$ 和管端 $r=R$ 时的绝对速度、速率及绝对加速度，并判断惯性平面内的轨迹形状。''',
9:r'''水平直管绕固定竖轴 $O$ 以恒角速率 $\Omega>0$ 转动，取管轴与固定 $X$ 轴的初始夹角为零。质点在 $t=0$ 从 $O$ 出发，装置控制其惯性系速率始终等于常数 $c$，且最初沿管向外运动。求 $r(t)$、$\dot r(t)$、首个向外阶段的终止时间与最大半径，并确定该阶段的惯性系轨迹。''',
10:r'''离心调速器的小球由长 $l$ 的轻杆与转轴上的固定铰点相连。轻杆所在的竖直平面以恒角速率 $\Omega$ 绕轴转动；杆与向下竖直线的夹角为 $\theta$，并以角速度 $\dot\theta$ 在该平面内摆动。在某时刻，$l=0.50\,\mathrm m$、$\theta=30^\circ$、$\dot\theta=0.20\,\mathrm{s^{-1}}$、$\Omega=6.0\,\mathrm{s^{-1}}$。求小球相对速率、牵连速率及惯性系速率。''',
11:r'''圆盘绕固定中心 $O$ 匀速转动，盘角速度为 $\Omega\vect e_z$。盘上半径为 $a$ 的同心圆槽内，一质点以相对角速度 $\nu\vect e_z$ 匀速运动。$\Omega$ 与 $\nu$ 均为有符号常数，俯视逆时针为正。求质点绝对速度、绝对加速度，并分别列出相对、牵连和科氏加速度。''',
12:r'''圆盘绕固定竖轴以角速度 $\Omega\vect e_z$ 匀速转动，质点在半径 $a$ 的同心圆槽内以相对角速度 $\nu=-\Omega$ 运动。求质点在惯性系中的速度和加速度，并逐项核验三项加速度如何抵消。说明“相对运动存在”与“绝对静止”能否同时成立。''',
13:r'''水平转盘以恒角速度 $\Omega\vect e_z$ 绕固定轴 $O$ 转动。圆槽中心 $C$ 固定在盘上，$\vect{OC}=d\vect e_1$，槽半径为 $a$。质点相对盘绕 $C$ 匀速运动，其相对角位置为 $\psi=\nu t$，其中 $\nu$ 为有符号常数。以盘上基矢表示质点位置，求惯性系加速度，并指出偏心距离 $d$ 带来的附加项。''',
14:r'''惯性系 $S$、中间系 $S_1$ 和随体系 $S_2$ 共用固定原点 $O$。$S_1$ 相对 $S$ 的角速度为 $\Om_1$，$S_2$ 相对 $S_1$ 的角速度为 $\Om_{21}$；质点 $P$ 固定在 $S_2$，位置矢量为 $\vect r$。两角速度须用同一空间基矢表示。分别选 $S_1$、$S_2$ 为动系计算 $P$ 的绝对速度，证明两种选择给出相同结果。''',
15:r'''刚体绕固定点 $O$ 运动，对称轴单位矢量为 $\vect n$。该轴与竖直方向夹角 $\alpha$ 保持不变，并以恒角速率 $\Omega_p$ 绕竖直轴进动；刚体还相对进动框架以角速率 $\omega_s$ 绕 $\vect n$ 自转。分别选择进动框架和完全随体框架，写出总角速度，并求轴上位置 $\vect r=h\vect n$ 处材料点的绝对速度。''',
16:r'''将地球视为半径 $R$ 的球，地心固定，自转角速度为 $\Omega_E$。一辆汽车沿经线向南行驶，相对地面的速率恒为 $u$；当前纬度为 $\lambda$。使用当地向东、向北、向上的基矢 $\vect e_E,\vect e_N,\vect e_U$，求汽车此刻的绝对速度与加速度。计算中须保留汽车沿球面运动的曲率项。''',
17:r'''动系绕通过固定原点 $O$、方向为单位矢量 $\vect n$ 的轴，以恒角速率 $\Omega$ 转动。质量为 $m$ 的质点固定在转轴上，位置为 $\vect r=h\vect n$，$h\ne0$。求该点的离心惯性力，并说明能否把离心力的大小直接写成 $m\Omega^2h$。''',
18:r'''水平转盘绕固定竖轴逆时针转动，$\Om=\Omega\vect e_z$，$\Omega>0$。质量为 $m$ 的质点位于盘上 $P$ 点，取向外为 $\vect e_r$、正切向为 $\vect e_\theta$。分别令其相对速度为 $+u\vect e_r$、$-u\vect e_r$、$+u\vect e_\theta$、$-u\vect e_\theta$，其中 $u>0$。求四种情形的科氏惯性力大小与方向。''',
19:r'''半径均为 $a$ 的两轮及皮带位于同一水平面，整体框架绕两轮中心连线中点 $O$ 以 $\Omega_c>0$ 逆时针转动。取轮心连线为 $x$ 轴，上直跨段中点 $P$ 的位置为 $a\vect e_y$。皮带相对框架顺时针循环，使 $P$ 处相对速度为 $u\vect e_x$。取该处质量微元为 $m$，求离心力、科氏惯性力及其合力，并判定合力改为向轴内的条件。''',
20:r'''一座舱只作竖直平动，取向上为 $z$ 轴，舱体加速度为有符号量 $A\vect e_z$，重力加速度为 $-g\vect e_z$。舱内密度为 $\rho$ 的不可压缩理想液体处于相对静止状态。两点位于同一液柱中，高度分别为 $z$ 与 $z+h$，$h>0$。求压强差 $p(z+h)-p(z)$，并讨论 $A$ 的正负对压强梯度的影响。''',
21:r'''飞行器在竖直平面内以速率 $V$ 沿曲率半径为 $\rho_c$ 的圆弧运动。乘员质量为 $m$，头脚轴暂与地面竖直方向一致；取座椅及约束对乘员的竖直合力向上为正。分别考察圆弧最低点与最高点，求有效竖直重力和有符号载荷因子 $n=N/(mg)$，并给出最高点失重的条件。''',
22:r'''质量为 $m$ 的物块位于水平转盘上，距固定竖轴 $a$。转盘角速度为 $\Omega(t)\vect e_z$，物块依靠静摩擦保持相对静止；物块与盘的静摩擦系数为 $\mu_s$，重力加速度为 $g$。求所需静摩擦力的径向、切向分量及大小，并写出不滑动条件。''',
23:r'''质量为 $m$ 的小球由长度 $l$ 的无质量刚杆连接到竖直转轴上的固定铰点。杆只能在随框架以恒角速率 $\Omega$ 转动的竖直平面内摆动，$\theta$ 从向下竖直线起算。忽略阻力，重力加速度为 $g$。求下半平面的相对平衡分支、倾斜分支出现的临界转速和杆力 $T$；再说明可承压刚杆是否还存在向上倒立分支。''',
24:r'''一轴上悬点的旋转摆由长 $l=0.50\,\mathrm m$ 的轻杆和质量 $m$ 的小球组成；摆动被限制在随框架以 $\Omega=6.0\,\mathrm{s^{-1}}$ 转动的径向竖直平面内，$g=9.80\,\mathrm{m/s^2}$。求稳定倾斜平衡角 $\theta_0$、单位质量杆力 $T/m$，以及在该平面内围绕平衡位置作小振动的角频率和周期。''',
25:r'''悬点 $A$ 固定在绕竖直轴匀速转动的框架上，距轴水平距离为 $a>0$。质量 $m$ 的小球由长 $l$ 的轻绳悬挂，在随框架转动的径向竖直平面内向轴外倾斜 $\varphi$，角度从悬点处向下铅垂线量起。已知框架角速率 $\Omega$ 和重力加速度 $g$。求相对平衡角应满足的方程以及绳张力 $T$。''',
26:r'''均匀细杆长 $L$、质量 $M$，上端 $O$ 装在水平无摩擦铰轴上。铰轴及杆的摆动平面绕通过 $O$ 的竖直轴，以恒角速率 $\Omega$ 转动。杆与向下竖直线夹角为 $\varphi$，重力加速度为 $g$。将离心力矩沿杆积分，求运动方程、相对平衡分支、临界转速及稳定平衡附近的微振动周期。''',
27:r'''圆柱形容器内的不可压缩理想液体与容器一起绕竖直轴以恒角速率 $\Omega$ 转动，并已达到相对静止。重力加速度 $g$ 均匀向下，自由表面处气压相同，忽略表面张力。取离轴距离为 $r$、竖直高度为 $z$，求自由表面 $z(r)$，并说明其积分常数应由什么条件确定。''',
28:r'''水平光滑直管绕固定竖轴以恒角速度 $\Omega\vect e_z$ 转动，质量为 $m$ 的珠子只受重力和管的约束。取穿过轴心、随管转动的有符号坐标 $x$，正切向为 $\vect e_2$。给定 $x(0)=a$、$\dot x(0)=u_0$，重力加速度为 $g$。求 $x(t)$、管对珠子的横向反力和竖直支持力。''',
29:r'''质量为 $m$ 的珠子在水平光滑径向管内滑动，管绕固定竖轴以恒角速率 $\Omega$ 转动。另有控制装置施加沿管的真实力，使珠子保持 $x(t)=a+ut$，其中 $a>0$、$u>0$。以沿管向外为正，求该控制力 $F_1(t)$、横向反力及控制力相对于管的功率，并判断被动光滑管能否独自维持此运动。''',
30:r'''水平圆盘以恒角速率 $\Omega$ 转动，穿过圆心的光滑直槽内有质量为 $m$ 的滑块。两根劲度系数均为 $k$ 的弹簧分别连接滑块与槽的两端，滑块在圆心时两弹簧均处于自然长度。取槽内有符号位移为 $x$，给定 $x(0)=x_0$、$\dot x(0)=u_0$，忽略阻力。求运动方程与临界转速，分别讨论低于、等于和高于临界转速的运动，并求横向槽壁反力。''',
31:r'''水平转盘的光滑径向直槽内，质量 $m=0.20\,\mathrm{kg}$ 的滑块由两根劲度系数各为 $k=5.0\,\mathrm{N/m}$ 的弹簧连接两端；在圆心处两弹簧均不变形。盘以恒角速率 $\Omega=5.0\,\mathrm{s^{-1}}$ 转动。滑块从 $x_0=0.040\,\mathrm m$ 处相对静止释放。求 $x(t)$、振动周期、槽壁对滑块的有符号横向反力 $N_2(t)$ 及最大侧压力大小。''',
32:r'''质点不受真实力，在惯性水平面内于 $t=0$ 从固定原点 $O$ 以速度 $u\vect E_X$ 出发。另取共原点的动系，以恒角速度 $\Omega\vect e_z$ 旋转，初始水平轴与惯性轴重合。求动系中的坐标 $x(t),y(t)$ 及轨迹，并代入含离心力、科氏力的动系方程核验。''',
33:r'''采用球形地球模型，半径 $R=6.371\times10^6\,\mathrm m$，纯引力加速度 $g_0=9.81\,\mathrm{m/s^2}$，自转角速率 $\Omega_E=7.292115\times10^{-5}\,\mathrm{s^{-1}}$。分别计算赤道、纬度 $45^\circ$ 及极点的自转离心修正；在 $45^\circ$ 处区分竖直、水平分量与总量，并估算铅垂偏角。''',
34:r'''球形地球模型取 $R=6.371\times10^6\,\mathrm m$、$\Omega_E=7.292115\times10^{-5}\,\mathrm{s^{-1}}$，且纯引力加速度不随纬度改变。实际地表的代表数值为：赤道约 $9.780\,\mathrm{m/s^2}$，极点约 $9.832\,\mathrm{m/s^2}$。求球形自转模型预测的极点与赤道重力差，与所给差值比较，并解释差异不能仅归为遗漏离心力的原因。''',
35:r'''质量为 $m$ 的物体在半径 $R$ 的球形地球上沿纬线行驶，纬度满足 $|\lambda|<\pi/2$。地球自转角速率为 $\Omega_E$，当地纯引力加速度为 $g_0$；物体相对地面的有向速度 $u$ 以东为正，忽略空气阻力。求道路约束力的径向分量 $N_U$，解释东、西向行驶的称重差，并说明保持纬线运动为何还需要水平引导力。''',
36:r'''在某海域观测到水团作近似圆周运动：从当地上方俯视为逆时针，周期为 $14\,\mathrm h$，速率约为 $0.20\,\mathrm{m/s}$。假设水平压强梯度及摩擦均可忽略，运动属于局部惯性圆；取地球恒星日 $D=23.9345\,\mathrm h$。判断所在半球，求纬度、科氏参数大小和圆轨道半径。''',
37:r'''北半球局部水平面取 $x$ 向东、$y$ 向北，科氏参数 $f=10^{-4}\,\mathrm{s^{-1}}$，空气密度 $\rho=1.2\,\mathrm{kg/m^3}$。直线等压线沿东西方向，压强向北增加，且 $\partial p/\partial y=1.2\times10^{-3}\,\mathrm{Pa/m}$、$\partial p/\partial x=0$。在稳态、无摩擦的地转近似下，求东西与南北风速分量，并说明压强梯度力和科氏力的方向。''',
38:r'''小型排水容器中的流动特征尺度为 $L=0.10\,\mathrm m$、速率为 $U=0.10\,\mathrm{m/s}$，当地科氏参数大小为 $|f|=10^{-4}\,\mathrm{s^{-1}}$。用罗斯贝数 $\mathrm{Ro}=U/(|f|L)$ 比较惯性与科氏效应，判断一般条件下能否仅凭排水旋涡的旋向识别南北半球，并指出哪些扰动可能控制旋向。''',
39:r'''在纬度 $\lambda$ 处，从地面上方高度 $h$ 相对地面静止释放小球。取释放点在地面的铅垂投影为原点，$x$ 向东、$y$ 向北、$z$ 向上，初位置为 $(0,0,h)$。忽略空气阻力、地表曲率和重力梯度，将有效重力 $g$ 视为常量，只保留地球自转角速率 $\Omega_E$ 的一阶效应。由运动方程积分求落地时的东西偏移。''',
40:r'''在纬度 $45^\circ$，分别从 $h=100\,\mathrm m$ 和 $h=500\,\mathrm m$ 高处相对地面静止释放小球。取 $g=9.81\,\mathrm{m/s^2}$、$\Omega_E=7.292115\times10^{-5}\,\mathrm{s^{-1}}$，忽略空气阻力、地表曲率和重力梯度，只保留自转的一阶修正。分别求下落时间与落地东偏量，并比较偏移随高度的变化规律。''',
41:r'''在纬度 $\lambda$ 的地面，从原点沿铅垂线以速度 $w_0>0$ 上抛小球，初始水平速度为零。取 $x$ 向东、$z$ 向上，有效重力 $g$ 为常量，忽略阻力和曲率，仅保留 $\Omega_E$ 的一阶项。求小球返回初始高度时的东西速度与东西位移，解释落点为什么偏西。''',
42:r'''在北纬 $45^\circ$，从地面上方 $h=100\,\mathrm m$ 的位置向东水平抛出小球，初始地面相对速度为 $u_0=100\,\mathrm{m/s}$，南北及竖直初速度均为零。取 $g=9.81\,\mathrm{m/s^2}$、$\Omega_E=7.292115\times10^{-5}\,\mathrm{s^{-1}}$，忽略阻力、曲率和重力梯度。保留自转一阶项，求飞行时间修正、东向射程修正及南北偏移。''',
43:r'''同一释放装置在若干高度 $h$ 进行落体实验，纬度 $\lambda$ 与有效重力 $g$ 相同。每次释放都有近似相同的小东向初速度偏差 $u_i$，其余初速度为零。忽略阻力、曲率及 $O(\Omega_Eu_i^2)$ 项，只保留初速度偏差和自转的首阶影响。求东向落点随高度的关系，并设计一种线性作图方法，将固定释放偏差与地球自转偏转区分开。''',
44:r'''长为 $l$ 的理想傅科摆在纬度 $\lambda$ 作小振幅运动。取当地 $x$ 向东、$y$ 向北，令 $\sigma=\Omega_E\sin\lambda$、$\omega_0=\sqrt{g/l}$、$\kappa=\sqrt{\omega_0^2+\sigma^2}$。将摆球沿东向拉开水平距离 $a\ll l$ 后相对地面静止释放，即 $x(0)=a,y(0)=\dot x(0)=\dot y(0)=0$。在线性傅科模型内求 $x(t),y(t)$，核验初条件，并解释慢转坐标中的轨迹。''',
45:r'''采用恒星日 $D=23.9345\,\mathrm h$。理想傅科摆分别设置在巴黎（北纬 $48.86^\circ$）、北京（北纬 $39.90^\circ$）和北极。求各处摆面转过 $360^\circ$ 的进动周期及每小时进动角度，注明俯视旋向。另取摆长 $l=67\,\mathrm m$、$g=9.81\,\mathrm{m/s^2}$，估算快振动周期，并说明这些理想周期是否依赖摆球质量。''',
46:r'''质量为 $m$ 的珠子在水平光滑径向管内自由滑动，管由电机维持恒角速率 $\Omega$。珠子从距轴 $a>0$ 处相对静止释放，运动规律为 $x=a\cosh\Omega t$，取真实势能零点使 $U=0$。分别由 $J=T'-m\Omega^2x^2/2$ 与 $J=E-\Omega L_z$ 计算雅可比量，核验二者一致，并判断惯性机械能 $E$ 是否守恒。''',
47:r'''质量为 $m$ 的物块被理想约束固定在水平转盘上，距固定竖轴 $a$，盘的角速率为 $\Omega(t)$。物块相对盘静止，真实势能 $U$ 不变。定义 $J=T'+U-m\Omega^2a^2/2$。求 $\dot J$、惯性系动能变化率及驱动功率，并核验 $\dot J=-\dot\Omega L_z$。'''
}
T={
1:r'''惯性系与动系共用固定原点和竖轴。动系以 $\Omega>0$ 匀速逆时针转动，$t=0$ 时两系水平轴重合。矢量 $\vect G=G\vect E_X$ 在惯性系中恒定。求动系分量与动系矢量导数，并代入运输定理核验惯性系导数。''',
2:r'''水平动系绕共同固定原点以恒角速度 $\Omega\vect e_z$ 转动。粒子相对动系绕轴作半径 $a$ 的匀速圆周运动，相对角速度为有符号常数 $\nu$；俯视逆时针为正。求绝对速度及加速度，列出加速度的各组成项，并检查 $\nu=0$ 与 $\nu=-\Omega$ 两种极限。''',
3:r'''水平直管的原点 $O'$ 具有惯性加速度 $A\vect E_X$，管同时绕 $O'$ 以恒角速度 $\Omega\vect e_z$ 转动。珠子由装置控制，沿管作 $x(t)=a+ut$ 的相对运动。$t=0$ 时管沿 $\vect E_X$，相应正切向为 $\vect E_Y$。求该时刻珠子的绝对加速度。''',
4:r'''一水平径向管绕固定竖轴以恒角速率 $\Omega>0$ 转动。珠子在 $t=0$ 从轴心出发，装置使其惯性系速率恒为 $c$，最初沿管向外运动。求首个向外阶段的最大径向位置与抵达时间，并解释此时相对径向速度的变化。''',
5:r'''质量 $m$ 的物体放在水平圆盘上，距固定竖轴 $a$，盘以恒角速率 $\Omega$ 转动。物体与盘间的静摩擦系数为 $\mu_s$，重力加速度为 $g$。求保持物体相对盘静止所需的摩擦力及允许的最大角速率。''',
6:r'''质量 $m$ 的珠子在水平光滑径向管内自由运动，管以恒角速率 $\Omega>0$ 绕固定竖轴转动，管端距轴 $L$。珠子在 $t=0$ 从 $x=a>0$ 处相对管静止释放，且 $L>a$。求首次到达管端的时间，以及到达瞬间珠子与管侧壁之间的压力大小；区分横向反力与竖直支持力。''',
7:r'''水平匀速转盘的光滑径向槽内有质量 $m$ 的滑块，两端分别连劲度系数为 $k$ 的弹簧，滑块在轴心时两弹簧均不变形。令初条件为 $x(0)=x_0$、$\dot x(0)=u_0$。求临界角速率及临界时的运动；再讨论高于临界且 $x_0=u_0=0$ 时的精确运动和对微小扰动的稳定性。''',
8:r'''质量 $m$ 的珠子在水平光滑径向管内滑动，管绕固定竖轴以恒角速率 $\Omega$ 转动。某时刻珠子的有符号坐标为 $x$，相对速度为 $\dot x\vect e_1$，管对珠子的横向反力为 $N_2\vect e_2$，其中 $N_2=2m\Omega\dot x$。求该反力在动系与惯性系中的瞬时功率，并验证惯性系功率等于 $\Omega\tau_z$。''',
9:r'''一长 $l$ 的轻杆将小球连到竖直转轴上的固定铰点，杆只能在随框架以恒角速率 $\Omega$ 转动的径向竖直平面内摆动。取与向下竖直线的有符号夹角为 $\theta$，重力加速度为 $g$。分别求 $\Omega<\sqrt{g/l}$ 和 $\Omega>\sqrt{g/l}$ 时下半平面的相对平衡，并用线性小振动判定稳定性。''',
10:r'''旋转摆的悬点距竖直转轴 $a=0.20\,\mathrm m$，摆长 $l=0.50\,\mathrm m$；摆线被铰链限制在随框架转动的径向竖直平面内，$g=9.81\,\mathrm{m/s^2}$。要求小球在向轴外倾斜 $\varphi_0=30^\circ$ 时相对平衡，角度从悬点处向下铅垂线量起。求框架角速率及该平面内的小振动角频率和周期。''',
11:r'''均匀细杆长 $L$、质量 $M$，上端通过无摩擦水平铰轴连接在固定竖直转轴上。杆在随框架以恒角速率 $\Omega$ 转动的竖直平面内摆动，夹角 $\varphi$ 从向下竖直线量起。求非竖直的稳定倾角、该分支出现的临界转速及其小振动角频率，并与杆端集中质点模型比较。''',
12:r'''质量 $m$、摆长 $l$ 的轴上悬点旋转摆，摆动被限制在随框架转动的径向竖直平面内；取 $\theta=0$ 为向下竖直位置。框架处于临界角速率 $\Omega^2=g/l$。将有效势在 $\theta=0$ 附近展开到首个非零项，判断平衡稳定性，并写出领先的非线性运动方程。''',
13:r'''把地球视为半径 $R$、地心固定的球，纯引力加速度为 $-g_0\vect e_U$，自转角速率为 $\Omega_E$。某静止地面点的纬度为 $\lambda$。求当地有效重力沿北向和天向的分量，以及铅垂方向相对地心径向的偏角；说明哪些纬度的水平分量为零。''',
14:r'''两辆质量均为 $m$ 的汽车在球形地球的同一纬度 $|\lambda|<\pi/2$ 上，沿纬线以相同地面相对速率 $U$ 分别向东、向西行驶。地球自转角速率为 $\Omega_E$，忽略空气阻力。求径向支持力之差 $N_{\rm west}-N_{\rm east}$，并对 $m=1000\,\mathrm{kg}$、$U=30\,\mathrm{m/s}$、$\lambda=45^\circ$ 作数值估计。''',
15:r'''北半球局部水平面取 $x$ 向东、$y$ 向北，科氏参数 $f>0$ 为常数。忽略水平压强梯度和摩擦，水团初位置为原点，初速度为 $U\vect e_E$，$U>0$。求位置随时间的关系、圆轨道中心、俯视旋向和最大南向位移。''',
16:r'''北半球存在稳态轴对称低压系统，局部密度为 $\rho$，科氏参数 $f>0$，径向压强梯度 $p_r=\dd p/\dd r>0$。取逆时针切向速度 $V$ 为正，忽略摩擦。分别在忽略与保留流线曲率加速度时建立地转风、梯度风关系，求通常的气旋分支并判断旋向。''',
17:r'''在北纬 $30^\circ$，从地面上方 $h=50\,\mathrm m$ 处相对地面静止释放小球。取 $g=9.81\,\mathrm{m/s^2}$、$\Omega_E=7.292115\times10^{-5}\,\mathrm{s^{-1}}$，忽略阻力、曲率和重力梯度。只保留自转一阶项，求下落时间、落地东偏量和该阶的南北偏移。''',
18:r'''在纬度 $\lambda$ 的地面，将小球以速度 $w_0>0$ 沿铅垂线上抛，初始水平速度为零。取 $x$ 向东、$z$ 向上，$c=\Omega_E\cos\lambda$，有效重力 $g$ 恒定，忽略阻力和曲率。只保留自转一阶项，求返回原高度时的东西速度与位移，并解释东西科氏力的变号为何不使位移抵消。''',
19:r'''在纬度 $\lambda$，从地面上方高度 $h$ 向北水平抛出小球，地面相对初速度为 $v_0\vect e_N$，$v_0>0$。取释放点的地面铅垂投影为原点，$x$ 向东、$y$ 向北、$z$ 向上；令 $\sigma=\Omega_E\sin\lambda$、$c=\Omega_E\cos\lambda$。忽略阻力、曲率及重力梯度，仅保留自转一阶项，求飞行时间和落点坐标，并讨论东西偏移的方向。''',
20:r'''在纬度 $\lambda$ 从高度 $h$ 向东水平抛出小球，初速度为 $u_0>0$。忽略阻力、曲率及重力梯度，有效重力为 $g$。令 $c=\Omega_E\cos\lambda$、零阶落地时间 $T_0=\sqrt{2h/g}$。求竖直科氏项引起的飞行时间修正 $\delta T$，并比较它对东向射程的贡献与落体东偏项，说明保留自转一阶时能否忽略前者。''',
21:r'''长 $l$ 的理想傅科摆在纬度 $\lambda$ 作小振动，$x$ 向东、$y$ 向北，$\zeta=x+\mathrm iy$。记 $\sigma=\Omega_E\sin\lambda$、$\kappa=\sqrt{g/l+\sigma^2}$。已知通解
\[\zeta=e^{-\mathrm i\sigma t}(A\cos\kappa t+B\sin\kappa t).\]
摆球由 $x=a,y=0$ 处相对地面静止释放。求复常数 $A,B$，核验初速度，并指出删去正弦项会怎样改变初条件。''',
22:r'''在北纬 $60^\circ$，分别考察理想小振幅傅科摆的慢进动和只受水平科氏力的水团惯性圆。取地球恒星日 $D=23.9345\,\mathrm h$，进动周期按有向主轴转过 $360^\circ$ 计。求两种周期，注明旋向，并解释为什么两者相差两倍。''',
23:r'''水平匀速转盘的光滑径向槽内，质量 $m$ 的滑块由两根劲度系数各为 $k$ 的弹簧连接两端；在轴心时两弹簧均不变形。盘角速率 $\Omega$ 恒定，滑块满足 $\ddot x+(2k/m-\Omega^2)x=0$。写出并证明雅可比量 $J$ 守恒，再求惯性机械能 $E$ 的变化率及其与驱动力矩功率的关系。''',
24:r'''惯性系中有一个方向固定的均匀水平力 $F_0\vect E_X$，其势能为 $U=-F_0X$。动系与惯性系共用固定原点，以恒角速度 $\Omega\vect e_z$ 转动，$t=0$ 时水平轴重合。将势写成动系坐标 $x,y,t$ 的函数，并据此解释：为何仅有“真实力保守”，仍不足以保证 $J=T'+U-m\Omega^2(x^2+y^2)/2$ 守恒？'''
}
assert len(E)==47 and len(T)==24
(P/'工作文件/完整题干.json').write_text(json.dumps({'examples':E,'exercises':T},ensure_ascii=False,indent=2))
print('71 question statements written')
